MEDIA_TOKEN_PATTERN='"(?:\\\\.|[^"\\\\])*"|\'(?:\\\\.|[^\'\\\\])*\'|`(?:\\\\.|[^`\\\\])*`|//[^\\n]*|/\\*[\\s\\S]*?\\*/|[A-Za-z_$][\\w$]*|\\d+(?:\\.\\d+)?|===|!==|=>|\\?\\.|&&|\\|\\||==|!=|<=|>=|\\+\\+|--|\\+=|-=|\\*=|/=|\\?\\?|[^\\s]'
MEDIA_BASELINE_SIGNATURE='c63c03da8ce3e8a054d9c9994a1b2040db2177b0a701964bae1b4e8eba2eae75'
def media_signature(text):
 return hashlib.sha256(json.dumps(re.findall(MEDIA_TOKEN_PATTERN,text),ensure_ascii=False).encode()).hexdigest()
pending={}
media_status='updated'
for filename in dict.fromkeys(row[0] for row in CHANGES):
 p=root/filename
 if p.is_symlink():raise SystemExit('CHAT_GUI_PATCH symlink_refused')
 original=p.read_text();s=original
 if p.name=='messengerMedia.js' and media_signature(original) in ['52b24ffc5b5f9fc373a5b7277a2c074c98ed7cef1e435a84ba23672eb9350e8e', '16d9784917e892e79f5907fc0c66a6bc2ceb6cd4501cf430fa9a9ae9791e41f0']:
  pending[filename]=(source/'apps/web/src/messengerMedia.js').read_text();continue
 for name,old,new in CHANGES:
  if name!=filename:continue
  if new in s:continue
  if s.count(old)!=1:
   if p.name=='messengerMedia.js':
    if media_signature(original)==MEDIA_BASELINE_SIGNATURE:
     s=(source/'apps/web/src/messengerMedia.js').read_text()
     media_status='updated';break
    s=original;media_status='preserved_existing';break
   raise SystemExit('CHAT_GUI_PATCH layout_mismatch='+p.name)
  s=s.replace(old,new,1)
 pending[filename]=s
print('CHAT_GUI_MEDIA='+media_status)
for name in ['chatWritingTools.js','chatWritingTools.css','conversationLook.js','conversationLook.css']:
 if (root/'apps/web/src'/name).is_symlink():raise SystemExit('CHAT_GUI_PATCH symlink_refused')
for name,s in pending.items():(root/name).write_text(s)
for name in ['chatWritingTools.js','chatWritingTools.css','conversationLook.js','conversationLook.css']:shutil.copy2(source/'apps/web/src'/name,root/'apps/web/src'/name)

(root/'apps/web/src/.chat-gui-media-result').write_text(media_status)
